-- Rachna OS production schema. Apply through Supabase migrations.
create extension if not exists pgcrypto;
create table if not exists organizations(id uuid primary key default gen_random_uuid(),name text not null,created_at timestamptz default now());
create table if not exists profiles(id uuid primary key references auth.users(id) on delete cascade,organization_id uuid references organizations(id) on delete set null,full_name text,role text default 'staff',created_at timestamptz default now());
create table if not exists customers(id uuid primary key default gen_random_uuid(),organization_id uuid not null references organizations(id) on delete cascade,name text not null,phone text,whatsapp text,email text,notes text,created_at timestamptz default now());
create table if not exists inquiries(id uuid primary key default gen_random_uuid(),organization_id uuid not null references organizations(id) on delete cascade,customer_id uuid references customers(id) on delete set null,source text,status text default 'new',owner_id uuid references profiles(id) on delete set null,event_name text,event_date_bs text,venue text,guest_count integer,budget numeric,notes text,created_at timestamptz default now(),updated_at timestamptz default now());
create table if not exists projects(id uuid primary key default gen_random_uuid(),organization_id uuid not null references organizations(id) on delete cascade,customer_id uuid references customers(id) on delete set null,inquiry_id uuid references inquiries(id) on delete set null,name text not null,status text default 'planning',brand text,quoted_total numeric default 0,internal_cost numeric default 0,customer_advance numeric default 0,vendor_reserve numeric default 0,date_range_bs text,created_at timestamptz default now());
create table if not exists event_functions(id uuid primary key default gen_random_uuid(),project_id uuid not null references projects(id) on delete cascade,name text not null,event_date date,event_date_bs text,start_time time,venue text,guest_count integer,notes text);
create table if not exists services(id uuid primary key default gen_random_uuid(),organization_id uuid not null references organizations(id) on delete cascade,brand text not null,name text not null,category text,base_price numeric default 0,internal_cost numeric default 0,active boolean default true);
create table if not exists project_services(id uuid primary key default gen_random_uuid(),project_id uuid not null references projects(id) on delete cascade,function_id uuid references event_functions(id) on delete set null,service_id uuid references services(id) on delete set null,name text not null,customer_price numeric default 0,internal_cost numeric default 0,quantity numeric default 1);
create table if not exists vendors(id uuid primary key default gen_random_uuid(),organization_id uuid not null references organizations(id) on delete cascade,name text not null,phone text,service_category text,area text,rate_guide text,reliability text default 'Medium',notes text,created_at timestamptz default now());
create table if not exists vendor_bookings(id uuid primary key default gen_random_uuid(),project_id uuid not null references projects(id) on delete cascade,function_id uuid references event_functions(id) on delete set null,vendor_id uuid not null references vendors(id) on delete cascade,quoted_cost numeric default 0,advance_paid numeric default 0,final_paid numeric default 0,status text default 'reserved');
create table if not exists team_members(id uuid primary key default gen_random_uuid(),organization_id uuid not null references organizations(id) on delete cascade,name text not null,role text,phone text,email text,active boolean default true,created_at timestamptz default now());
create table if not exists project_team(id uuid primary key default gen_random_uuid(),project_id uuid not null references projects(id) on delete cascade,team_member_id uuid not null references team_members(id) on delete cascade,function_id uuid references event_functions(id) on delete set null,responsibility text,rate numeric default 0);
create table if not exists tasks(id uuid primary key default gen_random_uuid(),organization_id uuid not null references organizations(id) on delete cascade,project_id uuid references projects(id) on delete cascade,function_id uuid references event_functions(id) on delete set null,title text not null,assignee_id uuid references profiles(id) on delete set null,due_date date,status text default 'todo',created_at timestamptz default now());
create table if not exists payments(id uuid primary key default gen_random_uuid(),organization_id uuid not null references organizations(id) on delete cascade,project_id uuid references projects(id) on delete cascade,direction text not null,party_type text not null,party_id uuid,amount numeric not null,payment_date date default current_date,method text,reference text,notes text,created_at timestamptz default now());
create table if not exists project_expenses(id uuid primary key default gen_random_uuid(),organization_id uuid not null references organizations(id) on delete cascade,project_id uuid references projects(id) on delete cascade,category text not null,description text not null,amount numeric not null,expense_date date default current_date,method text,notes text,created_at timestamptz default now());
create table if not exists production_costs(id uuid primary key default gen_random_uuid(),project_id uuid not null references projects(id) on delete cascade,function_id uuid references event_functions(id) on delete set null,brand text not null,category text not null,description text not null,quantity numeric default 1,unit_cost numeric default 0,notes text,created_at timestamptz default now());
create table if not exists quotations(id uuid primary key default gen_random_uuid(),project_id uuid not null references projects(id) on delete cascade,version integer default 1,status text default 'draft',customer_total numeric default 0,internal_total numeric default 0,notes text,created_at timestamptz default now());
create table if not exists quotation_items(id uuid primary key default gen_random_uuid(),quotation_id uuid not null references quotations(id) on delete cascade,function_id uuid references event_functions(id) on delete set null,service_id uuid references services(id) on delete set null,description text not null,quantity numeric default 1,customer_price numeric default 0,internal_cost numeric default 0);
create table if not exists aavartan_deliverables(id uuid primary key default gen_random_uuid(),project_id uuid not null references projects(id) on delete cascade,function_id uuid references event_functions(id) on delete set null,deliverable text not null,status text default 'pending',due_date date,delivered_at timestamptz);
create table if not exists documents(id uuid primary key default gen_random_uuid(),organization_id uuid not null references organizations(id) on delete cascade,project_id uuid references projects(id) on delete cascade,kind text not null,title text not null,url text,status text default 'draft',created_at timestamptz default now());
create table if not exists marketing_leads(id uuid primary key default gen_random_uuid(),organization_id uuid not null references organizations(id) on delete cascade,customer_id uuid references customers(id) on delete set null,campaign text,channel text,content text,spend numeric default 0,lead_status text default 'new',created_at timestamptz default now());
create or replace function public.my_org_id() returns uuid language sql stable security definer set search_path=public as $$ select organization_id from public.profiles where id=auth.uid() $$;
revoke execute on function public.my_org_id() from anon; grant execute on function public.my_org_id() to authenticated;
create or replace function public.apply_customer_advance(p_project_id uuid,p_amount numeric,p_method text default null,p_reference text default null) returns jsonb language plpgsql security definer set search_path=public as $$ declare v_org uuid; v_total numeric; v_received numeric; v_required numeric; v_reserve numeric; v_customer uuid; begin v_org:=public.my_org_id(); if v_org is null then raise exception 'No workspace'; end if; select quoted_total,customer_id,customer_advance into v_total,v_customer,v_received from projects where id=p_project_id and organization_id=v_org for update; if not found then raise exception 'Project not found'; end if; if coalesce(p_amount,0)<=0 then raise exception 'Advance must be greater than zero'; end if; v_received:=coalesce(v_received,0)+p_amount; v_required:=coalesce(v_total,0)*0.30; v_reserve:=v_received*0.15; insert into payments(organization_id,project_id,direction,party_type,party_id,amount,payment_date,method,reference) values(v_org,p_project_id,'in','customer',v_customer,p_amount,current_date,p_method,p_reference); update projects set customer_advance=v_received,vendor_reserve=v_reserve,status=case when v_received>=v_required then 'booked' else status end where id=p_project_id; return jsonb_build_object('received',v_received,'required',v_required,'vendor_reserve',v_reserve,'booked',v_received>=v_required); end $$;
revoke execute on function public.apply_customer_advance(uuid,numeric,text,text) from anon; grant execute on function public.apply_customer_advance(uuid,numeric,text,text) to authenticated;
create or replace function public.refresh_project_financials(p_project_id uuid) returns void language plpgsql security definer set search_path=public as $$ declare v_org uuid; v_quote numeric; v_cost numeric; begin v_org:=public.my_org_id(); select coalesce(sum(qi.customer_price*qi.quantity),0),coalesce(sum(qi.internal_cost*qi.quantity),0) into v_quote,v_cost from quotation_items qi join quotations q on q.id=qi.quotation_id where q.project_id=p_project_id and q.status<>'rejected' and exists(select 1 from projects p where p.id=q.project_id and p.organization_id=v_org); select v_cost+coalesce((select sum(quoted_cost) from vendor_bookings where project_id=p_project_id),0)+coalesce((select sum(quantity*unit_cost) from production_costs where project_id=p_project_id),0)+coalesce((select sum(amount) from project_expenses where project_id=p_project_id),0) into v_cost; update projects set quoted_total=v_quote,internal_cost=v_cost where id=p_project_id and organization_id=v_org; end $$;
revoke execute on function public.refresh_project_financials(uuid) from anon; grant execute on function public.refresh_project_financials(uuid) to authenticated;